CREATE TABLE `mp_situation_flow_classification` (
                                                    `pk` bigint(8) unsigned NOT NULL AUTO_INCREMENT,
                                                    `id` varchar(32) CHARACTER SET utf8 NOT NULL COMMENT 'ID',
                                                    `category_en` varchar(255) CHARACTER SET utf8 NOT NULL COMMENT '分类英文名称',
                                                    `category_zh` varchar(255) CHARACTER SET utf8 NOT NULL COMMENT '分类中文名称',
                                                    `severity` tinyint(3) NOT NULL COMMENT '严重性',
                                                    `create_time` datetime NOT NULL COMMENT '创建时间',
                                                    `update_time` datetime DEFAULT NULL COMMENT '更新时间',
                                                    PRIMARY KEY (`pk`)
) ENGINE=InnoDB AUTO_INCREMENT=45 DEFAULT CHARSET=utf8mb4 COMMENT='流量分类表';

